{"code":"import std.collection.*

func repair(q: LinkedList<Int64>, mark: ?LinkedListNode<Int64>, t: Int64): Int64 {
    if (q.isEmpty()) {
        return -1
    }
    match (mark) {
        case None => return -1
        case Some(node) =>
            var cur = node.prev
            var idx: Int64 = 1
            while (true) {
                match (cur) {
                    case None => return -1
                    case Some(n) =>
                        if (n.value >= t) {
                            return idx
                        }
                        idx += 1
                        cur = n.prev
                }
            }
    }
    return -1
}

main() {
    let q0 = LinkedList<Int64>([5, -2, -2, 6, 3])
    let r0 = repair(q0, q0.nodeAt(3), 2)
    println(r0 == 3 && q0.toArray() == [5, -2, -2, 6, 3])
    let q1 = LinkedList<Int64>([3, 1, 4, 4, -3])
    let r1 = repair(q1, q1.nodeAt(1), 4)
    println(r1 == -1 && q1.toArray() == [3, 1, 4, 4, -3])
}
"}

