{"code":"import std.collection.*

func repair(q: LinkedList<Int64>, mark: ?LinkedListNode<Int64>, t:Int64):Int64 {
    if(q.isEmpty()){return -1}
    if(mark.isNone()){return -1}
    var cur: ?LinkedListNode<Int64> = match (mark) {
        case Some(node) => node.prev
        case None => None
    }
    var index: Int64 = 0
    var prevValue: ?Int64 = None
    while (true) {
        match (cur) {
            case Some(node) =>
                index = index + 1
                let v = node.value
                match (prevValue) {
                    case Some(pv) =>
                        if (pv == v) {
                            return index
                        }
