        return 0
    }
    let mark = q.nodeAt(offset)
    match (mark) {
        case Some(node) =>
            var count: Int64 = 0
            var it = q.forward(node)
            // forward 从 mark 本身开始，先跳过标记本身
            if (it.next().isSome()) {
                while (true) {
                    match (it.next()) {
                        case Some(v) =>
                            if (v == t) {
                                break
                            }
                            if (v < 0) {
                                count++
                            }
                        case None => break
                    }
