func repair(q: LinkedList<Int64>, offset: Int64, t: Int64): Int64 {
    if (q.isEmpty()) {
        return 0
    }
    if (offset < 0 || offset >= q.size) {
        return 0
    }
    let markOpt = q.nodeAt(offset)
    if (markOpt.isNone()) {
        return 0
    }
    let mark = markOpt.getOrThrow()
    var count: Int64 = 0
    var it = q.backward(mark)
    while (true) {
        match (it.next()) {
            case Some(v) =>
                if (v == t) {
                    break
                }
                if (v < 0) {
                    let idx = offset - 1 - count
                    if (idx < 0) {
                        break
                    }
                    let nodeOpt = q.nodeAt(idx)
                    match (nodeOpt) {
                        case Some(n) =>
                            let old = q.remove(n)
                            q.addBefore(n, -old)
                            count = count + 1
                        case None => break
                    }
                }
            case None => break
        }
    }
    return count
}

